@push('scripts')
<script>
    document.querySelectorAll('[data-requester-picker]').forEach((picker) => {
        const select = picker.querySelector('[data-requester-select]');
        const name = picker.querySelector('[data-requester-name]');
        const email = picker.querySelector('[data-requester-email]');
        select?.addEventListener('change', () => {
            const option = select.selectedOptions[0];
            if (!option?.value) return;
            if (name) name.value = option.dataset.name || '';
            if (email) email.value = option.dataset.email || '';
        });
    });
    document.querySelectorAll('[data-fleet-destination-select]').forEach((select) => {
        const label = select.querySelector('[data-fleet-destination-label]');
        const checks = Array.from(select.querySelectorAll('[data-fleet-destination-check]'));
        const search = select.querySelector('[data-fleet-destination-search]');
        const options = Array.from(select.querySelectorAll('[data-fleet-destination-option]'));
        const syncLabel = () => { const amount = checks.filter((check) => check.checked).length; if (label) label.textContent = amount ? amount + ' centro(s) seleccionado(s)' : 'Selecciona uno o mas centros'; };
        checks.forEach((check) => check.addEventListener('change', syncLabel));
        search?.addEventListener('input', () => { const query = search.value.trim().toLocaleLowerCase('es'); options.forEach((option) => { option.hidden = query !== '' && !option.innerText.toLocaleLowerCase('es').includes(query); }); });
        syncLabel();
    });

    const fleetDrawerBackdrop = document.querySelector('[data-fleet-drawer-backdrop]');
    let fleetDrawerActive = null;
    let fleetDrawerTrigger = null;
    const closeFleetDrawer = () => {
        if (!fleetDrawerActive) return;
        fleetDrawerActive.classList.remove('is-open');
        fleetDrawerActive.setAttribute('aria-hidden', 'true');
        fleetDrawerBackdrop?.classList.remove('is-open');
        document.body.classList.remove('fleet-drawer-open');
        fleetDrawerTrigger?.focus();
        fleetDrawerActive = null;
        fleetDrawerTrigger = null;
    };
    document.querySelectorAll('[data-fleet-drawer-open]').forEach((trigger) => {
        trigger.addEventListener('click', () => {
            const drawer = document.getElementById('fleet-drawer-' + trigger.dataset.fleetDrawerOpen);
            if (!drawer) return;
            if (fleetDrawerActive && fleetDrawerActive !== drawer) {
                fleetDrawerActive.classList.remove('is-open');
                fleetDrawerActive.setAttribute('aria-hidden', 'true');
            }
            fleetDrawerActive = drawer;
            fleetDrawerTrigger = trigger;
            drawer.setAttribute('aria-hidden', 'false');
            drawer.classList.add('is-open');
            fleetDrawerBackdrop?.classList.add('is-open');
            document.body.classList.add('fleet-drawer-open');
            window.setTimeout(() => drawer.querySelector('[data-fleet-drawer-close]')?.focus(), 120);
        });
    });
    document.querySelectorAll('[data-fleet-drawer-close]').forEach((button) => button.addEventListener('click', closeFleetDrawer));
    fleetDrawerBackdrop?.addEventListener('click', closeFleetDrawer);
    document.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeFleetDrawer(); });
    document.querySelectorAll('[data-fleet-delete-form]').forEach((form) => {
        const reveal = form.querySelector('[data-fleet-delete-reveal]');
        const confirmation = form.querySelector('[data-fleet-delete-confirm]');
        const cancel = form.querySelector('[data-fleet-delete-cancel]');
        reveal?.addEventListener('click', () => { reveal.hidden = true; confirmation.hidden = false; confirmation.querySelector('button[type="submit"]')?.focus(); });
        cancel?.addEventListener('click', () => { confirmation.hidden = true; reveal.hidden = false; reveal.focus(); });
    });
</script>
@endpush
